class Solution {
public:
    int maximumBeauty(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        int best = 0;
        int i = 0;
        for (int j = 0; j < n; j++) {
            while (nums[j] - nums[i] > 2 * k) {
                i++;
            }
            best = max(best, j - i + 1);
        }
        return best;
    }
};
